// === Tab: sketch349982 ===
let p = new Array(200);
let limit = 100;//

function setup() {
  for (i = 0; i<p.length; i++) {
    p[i] = new Pa();
  }
  createCanvas(900, 900);
  background(255);

  noFill();
  stroke(0);
  strokeWeight(1);
}

function draw() {
  fill(255, 10);
  noStroke();
  rect(0, 0, width, height);
  for (i = 0; i<p.length; i++) {
    p[i].show(i);
  }
}

class Pa {
  x, y, vx, vy;
  constructor() {
    x = random(width);
    y = random(height);

    let a = random(TWO_PI);
    vx = cos(a)*5;
    vy = sin(a)*5;
  }

  function show(index) {
    x+=vx;
    y+= vy;
    for (i = index+1; i<p.length; i++) {
      let d = dist(x, y, p[i].x, p[i].y);
      if (d<limit) {
        stroke(0, map(d, limit/2, limit, 255, 0));
        line(x, y, p[i].x, p[i].y);
      }
    }
    x = lm(x, width);
    y = lm(y, width);
  }
}
function lm(a, b) {
  if (a<0) {
    return a+b;
  } 
  if (a>b) {
    return a-b;
  }
  return a;
}

